const show = async (label: string, fn: () => Promise<unknown>) => {
  try {
    console.log(label, '=>', JSON.stringify(await fn()))
  } catch (e) {
    console.log(label, '=> THROWS', (e as Error).name + ': ' + (e as Error).message)
