const multipartReq = () => {
  const fd = new FormData()
  fd.append('message', 'hello')
  return new Request('http://localhost/', { method: 'POST', body: fd })
}
const urlencodedReq = () =>
  new Request('http://localhost/', {
    method: 'POST',
    body: new URLSearchParams({ message: 'hello' }),
  })

let formDataCalls = 0
const origRes = Response.prototype.formData
Response.prototype.formData = function (...a: []) {
  formDataCalls++
  return origRes.apply(this, a)
}
const origReq = Request.prototype.formData
Request.prototype.formData = function (...a: []) {
  formDataCalls++
  return origReq.apply(this, a)
}

