  // P1: body already read as FormData through the HonoRequest, then parseBody()
  await show('P1 multipart  formData() -> parseBody()', async () => {
    const req = new HonoRequest(multipartReq())
    await req.formData()
    return await req.parseBody()
  })
  await show('P1 urlencoded formData() -> parseBody()', async () => {
    const req = new HonoRequest(urlencodedReq())
    await req.formData()
    return await req.parseBody()
  })
