    const req = new HonoRequest(multipartReq())
    await req.text()
    return await req.parseBody()
  })
  await show('P2 urlencoded text() -> parseBody()', async () => {
    const req = new HonoRequest(urlencodedReq())
    await req.text()
    return await req.parseBody()
  })
  // P3: how many platform formData() parses for parseBody() x2 and validator('form') + parseBody()
  {
    const req = new HonoRequest(multipartReq())
    formDataCalls = 0
    await req.parseBody()
    await req.parseBody()
    await req.parseBody({ all: true })
    console.log('P3 parseBody() x3 on one HonoRequest: platform formData() parses =', formDataCalls)
    console.log('P3 bodyCache keys after parseBody():', Object.keys(req.bodyCache))
  }
  {
    const app = new Hono()
    app.post(
      '/',
      validator('form', (v) => v),
      async (c) => {
        await c.req.parseBody()
        return c.json(Object.keys(c.req.bodyCache))
      }
    )
    formDataCalls = 0
    const res = await app.request(multipartReq())
    console.log(
      'P3 validator(form) + parseBody(): platform formData() parses =',
      formDataCalls,
      'bodyCache keys',
      await res.text()
    )
  }
  // P4: cloneRawRequest after parseBody()
  await show('P4 parseBody() -> cloneRawRequest().formData()', async () => {
    const req = new HonoRequest(multipartReq())
    await req.parseBody()
    const cloned = await cloneRawRequest(req)
    return Object.fromEntries(await cloned.formData())
  })
  // P5: text() after parseBody(): original bytes or re-serialised?
  await show('P5 urlencoded parseBody() -> text()', async () => {
    const req = new HonoRequest(urlencodedReq())
    await req.parseBody()
    return (await req.text()).slice(0, 60)
  })
  // P6: mixed-case guard, raw Request
  await show('P6 raw Request Application/X-WWW-Form-Urlencoded', () =>
    parseBody(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'message=hello',
        headers: { 'Content-Type': 'Application/X-WWW-Form-Urlencoded' },
      })
    )
  )
  // P7: platform alone
  await show('P7 platform Request.formData() with Multipart/Form-Data', async () => {
    const src = multipartReq()
    const ct = src.headers.get('Content-Type')!.replace('multipart/form-data', 'Multipart/Form-Data')
    const r = new Request('http://localhost/', {
      method: 'POST',
      body: await src.arrayBuffer(),
      headers: { 'Content-Type': ct },
    })
    return Object.fromEntries(await origReq.call(r))
  })
}
main()
