import { HonoRequest } from 'SRC/request'
const N = 64 * 1024 * 1024
const build = () => {
  const fd = new FormData()
  fd.append('file', new Blob([new Uint8Array(N)]), 'a.bin')
  const res = new Response(fd)
  return new Request('http://localhost/', {
    method: 'POST',
    body: res.body,
    headers: { 'Content-Type': res.headers.get('Content-Type')! },
    // @ts-expect-error duplex
    duplex: 'half',
  })
}
const mb = (n: number) => (n / 1024 / 1024).toFixed(0) + 'MB'
const settle = async () => {
  for (let i = 0; i < 5; i++) {
    await new Promise((r) => setTimeout(r, 50))
    ;(globalThis as any).gc()
  }
}
const main = async () => {
  const req = new HonoRequest(build())
  await settle()
  const before = process.memoryUsage()
  const body = await req.parseBody()
  await settle()
  const after = process.memoryUsage()
  console.log(
    'retained after parseBody() of a 64MB upload (req + parsed body still referenced):',
    'arrayBuffers +' + mb(after.arrayBuffers - before.arrayBuffers),
    'external +' + mb(after.external - before.external),
    'rss +' + mb(after.rss - before.rss),
    '| file size', (body.file as File).size,
    '| cache keys', Object.keys(req.bodyCache).join(',')
  )
}
main()
